pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // The test contract is the current owner, so it can transfer ownership.
        c.transferOwnership(newOwner);

        // A third party (caller, different from the owner) queries the owner.
        vm.prank(caller);
        address reported = c.owner();

        // Rule: owner() reports the actual stored owner (newOwner), no matter who asks.
        assertTrue(reported == newOwner, "owner() must return the stored owner regardless of caller");
    }
}

