pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newX, address callerY) public {
        vm.assume(callerY != address(0));
        vm.assume(callerY != address(this));
        // Transfer ownership to an arbitrary fuzzed address from the deployer.
        c.transferOwnership(newX);
        // From a different address Y, an owner-only call must revert.
        vm.prank(callerY);
        bool ok;
        try c.renounceOwnership() { ok = true; } catch { ok = false; }
        // Rule: for any X and any Y != X, only X may perform owner-only actions.
        assertTrue(!ok);
    }
}

