pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.renounceOwnership() {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: if the renounce call completes, the owner must now be the
        // zero address; and the deployer (the original owner) can always renounce.
        // Mutant: owner() always returns address(0), so even the deployer's call
        // reverts (ok == false) while owner() remains non-zero -> assertion fails.
        assertTrue(ok ? (c.owner() == address(0)) : (caller != address(this)));
    }
}

