pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address actor) public {
        // Any non-owner actor: the deployer (this test contract) is excluded so the
        // ownership check must genuinely reject the caller. Keep domain wide.
        vm.assume(actor != address(this));

        bool ok;
        vm.prank(actor);
        try c.renounceOwnership() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ANY caller that is not the current owner,
        // renounceOwnership() reverts (ownership is unchanged/protected).
        // The mutant's owner() returns address(0), so a call from address(0)
        // passes _checkOwner and succeeds, breaking the rule.
        assertTrue(!ok, "non-owner must not be able to renounce ownership");
    }
}

