import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actor) public {
        // Admissible domain: any nonzero address may be appointed as caller
        vm.assume(actor != address(0));

        // The deployer (address(this)) is the stored owner, so any onlyOwner
        // action it takes must succeed. Drive the surface via setCaller.
        vm.prank(address(this));
        bool ok;
        try c.setCaller(actor) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for every nonzero fuzzed actor, the owner can execute
        // setCaller(actor). The mutant's owner() returns address(0), so the
        // onlyOwner check always fails and this call always reverts.
        assertTrue(ok);
    }
}

