pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actor, uint256 cfg) public {
        vm.assume(actor != address(0));
        cfg = bound(cfg, 1, type(uint256).max);

        // The stored owner delegates the onlyCaller role to the fuzzed actor.
        vm.prank(address(this));
        c.setCaller(actor);

        // The delegated actor must be able to change the configuration.
        vm.prank(actor);
        bool ok;
        try c.setCfg(cfg) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.deadCfg() == cfg);
    }
}
